            }
            if (request.powerKw().compareTo(BigDecimal.ZERO) < 0
                    || request.powerKw().compareTo(MAX_POWER_KW) > 0) {
                return "负载接入功率超限: 读数 " + request.powerKw() + " kW，计划上限 200 kW";
            }
        }
        return null;
    }

